@import "tailwindcss";

:root {
  --color-brand-primary: #1c1917;
  --color-brand-accent: #78716c;
  --font-serif: Georgia, Cambria, "Times New Roman", Times, serif;
}

body {
  margin: 0;
  padding: 0;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  color: #1c1917;
  background-color: #fafaf9;
}

export type HeroProps = {
  eyebrow?: string;
  heading?: string;
  description?: string;
  actionLabel?: string;
  actionHref?: string;
  imageSrc?: string;
  imageAlt?: string;
};

export default function Hero({
  eyebrow = "New collection",
  heading = "Objects for everyday rituals.",
  description = "Quiet essentials, thoughtfully made for the spaces you call home.",
  actionLabel = "Explore the collection",
  actionHref = "/collections/new",
  imageSrc = "/static/storefront/theme-preview-default.png",
  imageAlt = "A neutral collection of ceramic objects",
}: HeroProps) {
  return (
    <section
      data-morph-section="hero"
      data-morph-node="hero-root"
      className="grid min-h-[42rem] bg-stone-100 lg:min-h-[50rem] lg:grid-cols-[minmax(0,0.82fr)_minmax(0,1.18fr)]"
    >
      <div className="flex items-center px-[clamp(1.75rem,6vw,6rem)] py-20">
        <div className="max-w-xl">
          <p
            data-morph-node="hero-eyebrow"
            data-morph-element="eyebrow"
            className="text-xs font-medium uppercase tracking-[0.24em] text-stone-500"
          >
            {eyebrow}
          </p>
          <h1
            data-morph-node="hero-heading"
            data-morph-element="heading"
            className="mt-6 font-serif text-[clamp(3.25rem,7vw,7rem)] leading-[0.88] tracking-[-0.055em] text-stone-950"
          >
            {heading}
          </h1>
          <p
            data-morph-node="hero-description"
            data-morph-element="description"
            className="mt-7 max-w-md text-base leading-7 text-stone-600"
          >
            {description}
          </p>
          <div className="mt-8">
            <a
              href={actionHref}
              data-morph-node="hero-action"
              data-morph-element="action"
              className="inline-flex items-center justify-center rounded-md bg-stone-900 px-6 py-3 text-sm font-medium text-white transition-colors hover:bg-stone-800"
            >
              {actionLabel}
            </a>
          </div>
        </div>
      </div>
      <div
        data-morph-node="hero-image"
        data-morph-element="image"
        className="min-h-[30rem] overflow-hidden lg:min-h-0"
      >
        <img
          src={imageSrc}
          alt={imageAlt}
          className="size-full object-cover"
        />
      </div>
    </section>
  );
}

import { createContext, useContext } from "react";

export type MorphContentSlots = Record<string, Record<string, unknown>>;

const MorphContentContext = createContext<MorphContentSlots>({});

export const MorphContentProvider = MorphContentContext.Provider;

/** Reads the stored values for one content slot. */
export function content(slotId: string): Record<string, unknown> {
  const slots = useContext(MorphContentContext);
  return slots[slotId] ?? {};
}

import { createRouter } from "@tanstack/react-router";
import { routeTree } from "./routeTree.gen";

export function getRouter() {
  return createRouter({
    routeTree,
    scrollRestoration: true,
  });
}

declare module "@tanstack/react-router" {
  interface Register {
    router: ReturnType<typeof getRouter>;
  }
}

import type { ReactNode } from "react";
import Header from "../components/Header";
import Footer from "../components/Footer";

export type HomePageProps = {
  storeName?: string;
  copyrightText?: string;
  children?: ReactNode;
};

export default function HomePage({
  storeName = "Online Store",
  copyrightText = "© Online Store",
  children,
}: HomePageProps) {
  return (
    <div
      data-morph-node="page-root"
      className="min-h-screen bg-stone-50 text-neutral-950"
    >
      <Header storeName={storeName} />
      {children}
      <Footer storeName={storeName} copyrightText={copyrightText} />
    </div>
  );
}

import type { ReactNode } from "react";
import { HeadContent, Outlet, Scripts, createRootRoute } from "@tanstack/react-router";
import StorefrontLayout from "../layouts/StorefrontLayout";
import "../styles/global.css";

export const Route = createRootRoute({
  head: () => ({
    meta: [
      { charSet: "utf-8" },
      { name: "viewport", content: "width=device-width, initial-scale=1" },
      { title: "Online Store" },
    ],
  }),
  component: RootComponent,
  shellComponent: RootDocument,
});

function RootComponent() {
  return (
    <StorefrontLayout>
      <Outlet />
    </StorefrontLayout>
  );
}

function RootDocument({ children }: Readonly<{ children: ReactNode }>) {
  return (
    <html lang="en">
      <head>
        <HeadContent />
      </head>
      <body>
        {children}
        <Scripts />
      </body>
    </html>
  );
}

import { createFileRoute } from "@tanstack/react-router";
import { content } from "../morph/content";
import CategoryShowcase from "../components/CategoryShowcase";
import EditorialIntro from "../components/EditorialIntro";
import Hero from "../components/Hero";
import ImageWithText from "../components/ImageWithText";
import Newsletter from "../components/Newsletter";
import Principles from "../components/Principles";

export const Route = createFileRoute("/")({
  component: HomeRoute,
});

function HomeRoute() {
  return (
    <main data-morph-node="home-route">
      <Hero {...content("starter-hero")} />
      <EditorialIntro {...content("starter-introduction")} />
      <CategoryShowcase {...content("starter-categories")} />
      <ImageWithText {...content("starter-story")} />
      <Principles {...content("starter-principles")} />
      <Newsletter {...content("starter-newsletter")} />
    </main>
  );
}

export type EditorialIntroProps = {
  label?: string;
  heading?: string;
  body?: string;
};

export default function EditorialIntro({
  label = "About",
  heading = "Fewer things. Better chosen.",
  body = "Crafted with intention for long-lasting quality.",
}: EditorialIntroProps) {
  return (
    <section
      data-morph-section="editorial-intro"
      data-morph-node="editorial-intro-root"
      className="bg-stone-50 px-[clamp(1.75rem,7vw,7rem)] py-[clamp(6rem,12vw,11rem)]"
    >
      <div className="grid gap-10 border-t border-stone-300 pt-8 lg:grid-cols-[0.55fr_1.45fr]">
        <p
          data-storefront-field="label"
          data-morph-node="editorial-intro-label"
          data-morph-element="label"
          className="text-xs font-medium uppercase tracking-[0.22em] text-stone-500"
        >
          {label}
        </p>
        <div data-morph-node="editorial-intro-content" data-morph-element="content">
          <h2
            data-storefront-field="heading"
            data-morph-node="editorial-intro-heading"
            data-morph-element="heading"
            className="max-w-4xl font-serif text-[clamp(3rem,6vw,6.5rem)] leading-[0.92] tracking-[-0.045em] text-stone-950"
          >
            {heading}
          </h2>
          <p
            data-storefront-field="body"
            data-morph-node="editorial-intro-body"
            data-morph-element="body"
            className="ml-auto mt-10 max-w-xl text-lg leading-8 text-stone-600"
          >
            {body}
          </p>
        </div>
      </div>
    </section>
  );
}

export type CategoryShowcaseItem = {
  title?: string;
  caption?: string;
  href?: string;
  imageSrc?: string;
  imageAlt?: string;
  imagePosition?: string;
};

export type CategoryShowcaseProps = {
  heading?: string;
  items?: CategoryShowcaseItem[];
};

export default function CategoryShowcase({
  heading = "Shop by collection",
  items = [],
}: CategoryShowcaseProps) {
  return (
    <section
      data-morph-section="category-showcase"
      data-morph-node="category-showcase-root"
      className="bg-stone-900 px-[clamp(1.25rem,4vw,4rem)] py-[clamp(5rem,9vw,9rem)] text-stone-100"
    >
      <div className="mb-12 flex items-end justify-between border-b border-stone-700 pb-6">
        <h2
          data-storefront-field="heading"
          data-morph-node="category-showcase-heading"
          data-morph-element="heading"
          className="font-serif text-[clamp(2.5rem,5vw,5rem)] tracking-[-0.04em]"
        >
          {heading}
        </h2>
        <span className="hidden text-xs uppercase tracking-[0.2em] text-stone-400 sm:block">
          The collection
        </span>
      </div>
      <div
        data-morph-node="category-showcase-grid"
        data-morph-element="grid"
        className="grid gap-4 lg:grid-cols-3"
      >
        {items.map((item, index) => (
          <a
            key={item.href ?? index}
            href={item.href ?? "#"}
            data-storefront-field-path={`items.${index}`}
            data-morph-node="category-showcase-item"
            data-morph-element="collection-item"
            className="group block border-t border-stone-700 pt-4 lg:border-t-0 lg:pt-0"
          >
            <div className="aspect-[4/5] overflow-hidden bg-stone-800">
              <img
                src={item.imageSrc ?? "/static/storefront/theme-preview-default.png"}
                alt={item.imageAlt ?? "Collection item"}
                style={{ objectPosition: item.imagePosition ?? "center" }}
                className="size-full object-cover opacity-80 transition-transform duration-500 ease-out group-hover:scale-[1.025]"
              />
            </div>
            <div className="flex gap-5 py-5">
              <span className="pt-1 text-xs text-stone-500">{index + 1}</span>
              <div>
                <h3
                  data-storefront-field-path={`items.${index}.title`}
                  className="font-serif text-2xl"
                >
                  {item.title ?? "Collection"}
                </h3>
                <p
                  data-storefront-field-path={`items.${index}.caption`}
                  className="mt-2 max-w-xs text-sm leading-6 text-stone-400"
                >
                  {item.caption ?? ""}
                </p>
              </div>
            </div>
          </a>
        ))}
      </div>
    </section>
  );
}

export type ImageWithTextProps = {
  eyebrow?: string;
  heading?: string;
  body?: string;
  actionLabel?: string;
  actionHref?: string;
  imageSrc?: string;
  imageAlt?: string;
  imagePosition?: string;
};

export default function ImageWithText({
  eyebrow = "",
  heading = "Story",
  body = "",
  actionLabel = "Explore",
  actionHref = "#",
  imageSrc = "/static/storefront/theme-preview-default.png",
  imageAlt = "Image with text",
  imagePosition = "center",
}: ImageWithTextProps) {
  return (
    <section
      data-morph-section="image-with-text"
      data-morph-node="image-with-text-root"
      className="grid bg-[#d8d0c3] lg:grid-cols-2"
    >
      <div
        data-morph-node="image-with-text-image"
        data-morph-element="image"
        className="min-h-[32rem] overflow-hidden lg:min-h-[52rem]"
      >
        <img
          src={imageSrc}
          alt={imageAlt}
          style={{ objectPosition: imagePosition }}
          className="size-full scale-110 object-cover"
        />
      </div>
      <div className="flex items-center px-[clamp(2rem,7vw,7rem)] py-20">
        <div data-morph-node="image-with-text-content" data-morph-element="content" className="max-w-xl">
          <p
            data-storefront-field="eyebrow"
            data-morph-node="image-with-text-eyebrow"
            data-morph-element="eyebrow"
            className="text-xs font-medium uppercase tracking-[0.22em] text-stone-600"
          >
            {eyebrow}
          </p>
          <h2
            data-storefront-field="heading"
            data-morph-node="image-with-text-heading"
            data-morph-element="heading"
            className="mt-5 font-serif text-[clamp(3rem,5vw,5.5rem)] leading-[0.94] tracking-[-0.045em] text-stone-950"
          >
            {heading}
          </h2>
          <p
            data-storefront-field="body"
            data-morph-node="image-with-text-body"
            data-morph-element="body"
            className="mt-7 text-base leading-7 text-stone-700"
          >
            {body}
          </p>
          <a
            href={actionHref}
            data-storefront-field="actionLabel"
            data-morph-node="image-with-text-action"
            data-morph-element="action"
            className="mt-9 inline-flex border-b border-current pb-1 text-sm font-medium"
          >
            {actionLabel}
          </a>
        </div>
      </div>
    </section>
  );
}

export type NewsletterProps = {
  eyebrow?: string;
  heading?: string;
  body?: string;
  placeholder?: string;
  actionLabel?: string;
};

export default function Newsletter({
  eyebrow = "Stay connected",
  heading = "Join our newsletter",
  body = "",
  placeholder = "Enter your email",
  actionLabel = "Subscribe",
}: NewsletterProps) {
  return (
    <section
      data-morph-section="newsletter"
      data-morph-node="newsletter-root"
      className="bg-[#b7ad9d] px-[clamp(1.75rem,8vw,8rem)] py-[clamp(6rem,11vw,10rem)]"
    >
      <div data-morph-node="newsletter-content" data-morph-element="content" className="mx-auto max-w-4xl text-center">
        <p
          data-storefront-field="eyebrow"
          data-morph-node="newsletter-eyebrow"
          data-morph-element="eyebrow"
          className="text-xs font-medium uppercase tracking-[0.24em] text-stone-700"
        >
          {eyebrow}
        </p>
        <h2
          data-storefront-field="heading"
          data-morph-node="newsletter-heading"
          data-morph-element="heading"
          className="mt-6 font-serif text-[clamp(3rem,6vw,6rem)] leading-[0.92] tracking-[-0.045em] text-stone-950"
        >
          {heading}
        </h2>
        <p
          data-storefront-field="body"
          data-morph-node="newsletter-body"
          data-morph-element="body"
          className="mx-auto mt-6 max-w-lg text-base leading-7 text-stone-700"
        >
          {body}
        </p>
        <div
          data-morph-node="newsletter-form"
          data-morph-element="form"
          className="mx-auto mt-10 flex max-w-xl border-b border-stone-800 py-3 text-left"
          aria-label={placeholder}
        >
          <span data-storefront-field="placeholder" className="flex-1 text-sm text-stone-700">
            {placeholder}
          </span>
          <span data-storefront-field="actionLabel" className="text-sm font-medium text-stone-950">
            {actionLabel}
          </span>
        </div>
      </div>
    </section>
  );
}

import { clsx as cn } from "clsx";

export type PrincipleItem = {
  id?: string;
  number?: string;
  title?: string;
  body?: string;
};

export type PrinciplesProps = {
  items?: PrincipleItem[];
  label?: string;
};

const morphInstanceClasses: Record<string, string> = {};

export default function Principles({
  items = [],
  label = "Why we choose differently",
}: PrinciplesProps) {
  return (
    <section
      data-morph-section="principles"
      data-morph-node="principles-root"
      className="bg-stone-50 px-[clamp(1.75rem,6vw,6rem)] py-[clamp(6rem,10vw,9rem)]"
    >
      <p
        data-storefront-field="label"
        data-morph-node="principles-label"
        data-morph-element="label"
        className="mb-14 text-xs font-medium uppercase tracking-[0.22em] text-stone-500"
      >
        {label}
      </p>
      <div
        data-morph-node="principles-grid"
        data-morph-element="grid"
        className="grid border-t border-stone-300 lg:grid-cols-3"
      >
        {items.map((item, idx) => (
          <article
            key={item.id ?? item.number ?? idx}
            data-morph-node="principle-card"
            data-morph-element="principle-card"
            className={cn(
              "border-b border-stone-300 py-8 lg:border-b-0 lg:border-r lg:px-8 lg:first:pl-0 lg:last:border-r-0",
              morphInstanceClasses[`${item.id}:principle-card`],
            )}
          >
            <span
              data-morph-node="principle-number"
              data-morph-element="number"
              className="text-xs text-stone-400"
            >
              {item.number ?? ("0" + (idx + 1))}
            </span>
            <h3
              data-morph-node="principle-title"
              data-morph-element="title"
              className={cn(
                "mt-12 font-serif text-3xl tracking-tight text-stone-950",
                morphInstanceClasses[`${item.id}:principle-title`],
              )}
            >
              {item.title ?? ""}
            </h3>
            <p
              data-morph-node="principle-body"
              data-morph-element="body"
              className={cn(
                "mt-4 max-w-sm text-sm leading-6 text-stone-600",
                morphInstanceClasses[`${item.id}:principle-body`],
              )}
            >
              {item.body ?? ""}
            </p>
          </article>
        ))}
      </div>
    </section>
  );
}

